async function loadTemplate() {
  const localCandidates = [
    'c:/Users/acc/Downloads/badao/taomay.yml',
    'c:/Users/acc/Downloads/badao/taomay.yaml',
    path.resolve(process.cwd(), '.github/workflows/taomay.yml'),
