// ----------------- ĐỒNG BỘ TRẠNG THÁI MÁY & ID/PIN -----------------
async function syncMachine(name, forceRefresh = false) {
  const m = store.machines[name] = store.machines[name] || R.machines[name] || { name, created: Date.now() };
  try {
    const stateBranch = `aistv-state-${name}`;

    // Đọc trạng thái từ Repo Gốc
    try {
      const stateRes = await gh('GET', STORAGE_REPO, `/contents/status.json?ref=${encodeURIComponent(stateBranch)}`);
      if (stateRes && stateRes.content) {
        const rawJson = Buffer.from(stateRes.content.replace(/\s+/g, ''), 'base64').toString('utf8');
        const st = JSON.parse(rawJson);
        if (st.status) m.repoStatus = st.status;
        const devId = st.deviceId || st.gvId;
        if (devId && !devId.includes('Xem')) m.gvId = String(devId).trim();
        if (st.pin || st.gvPin) m.gvPin = String(st.pin || st.gvPin).trim();
        if (st.pass) m.pass = String(st.pass).trim();
        if (st.updatedVn) m.updatedVn = st.updatedVn;
        if (st.updatedUtc) m.updatedUtc = st.updatedUtc;
        if (st.status === 'Online' || st.status === 'Running') {
          m.isOnline = true;
          m.ready = true;
        } else if (st.status === 'Stopped') {
          m.isOnline = false;
          m.ready = false;
        }
      }
    } catch {}

    // Dự phòng: đọc từ ip.txt trên Repo Gốc
    if (!m.gvId) {
      try {
        const ipRes = await gh('GET', STORAGE_REPO, `/contents/ip.txt?ref=${encodeURIComponent(stateBranch)}`);
        if (ipRes && ipRes.content) {
          const ipTxt = Buffer.from(ipRes.content.replace(/\s+/g, ''), 'base64').toString('utf8');
          const idM = ipTxt.match(/GameViewer ID\s*:\s*([0-9]{6,12})/i);
          const pinM = ipTxt.match(/Mã PIN(?:\s*\(Code\))?\s*:\s*([A-Za-z0-9@_.-]+)/i);
          const statM = ipTxt.match(/Trạng thái\s*:\s*([^\r\n]+)/i);
          if (idM && idM[1]) m.gvId = idM[1].trim();
          if (pinM && pinM[1]) m.gvPin = pinM[1].trim();
          if (statM && statM[1]) {
            m.repoStatus = statM[1].trim();
            if (m.repoStatus.includes('Online')) { m.isOnline = true; m.ready = true; }
            else if (m.repoStatus.includes('Stopped')) { m.isOnline = false; }
          }
        }
      } catch {}
    }

    // Kiểm tra tiến trình workflow trên Runner Repo
    const listRes = await gh('GET', RUNNER_REPO, `/actions/workflows/${name}.yml/runs?per_page=1`);
    const run = (listRes.workflow_runs && listRes.workflow_runs[0]) || null;
    if (!run) {
      m.status = m.repoStatus || 'no_run';
      return m;
    }

    m.runId = run.id;
    m.runUrl = run.html_url;
    m.status = run.status;
    m.conclusion = run.conclusion;
    m.startedAt = run.run_started_at ? new Date(run.run_started_at).getTime() : new Date(run.created_at).getTime();

    const durMin = m.durationMin || 300;
    const elapsedSec = Math.max(0, Math.floor((Date.now() - m.startedAt) / 1000));
    m.elapsedSec = elapsedSec;
    m.remainSec = Math.max(0, (durMin * 60) - elapsedSec);

    if (run.status === 'completed') {
      m.isOnline = false;
      m.ready = false;
    }

    // Đọc ID/PIN từ Annotations/Logs nếu chưa bắt được
    if (!m.gvId && (run.status === 'in_progress' || run.status === 'completed')) {
      const jobsRes = await gh('GET', RUNNER_REPO, `/actions/runs/${run.id}/jobs?per_page=1`);
      const job = (jobsRes.jobs && jobsRes.jobs[0]) || null;
      if (job) {
        m.jobId = job.id;
        try {
          const anns = await gh('GET', RUNNER_REPO, `/check-runs/${job.id}/annotations?per_page=20`);
          if (Array.isArray(anns)) {
            const gvAnn = anns.find(a => a.title && a.title.includes('GAMEVIEWER'));
            if (gvAnn && gvAnn.message) {
              const msg = gvAnn.message;
              const idM = msg.match(/ID=([^\s|]+)/);
              const pinM = msg.match(/PIN=([^\s|]+)/);
              const passM = msg.match(/PASS=([^\s|]+)/);
              if (idM && idM[1] && !idM[1].includes('Xem')) m.gvId = idM[1].trim();
              if (pinM && pinM[1]) m.gvPin = pinM[1].trim();
              if (passM && passM[1]) m.pass = passM[1].trim();
              m.ready = true;
            }
          }
        } catch {}
      }
    }
  } catch (err) {
    m.error = err.message;
  }
  return m;
}

// ----------------- CHỨC NĂNG QUÉT TẤT CẢ FILE .YML Ở RUNNER REPO -----------------
async function scanAndRebuildWorkflows(upgradeToLatest = false) {
  const contents = await gh('GET', RUNNER_REPO, '/contents/.github/workflows');
  if (!Array.isArray(contents)) {
    throw new Error(`Không đọc được thư mục .github/workflows trên ${RUNNER_REPO}`);
  }

  const ymlFiles = contents.filter(f => f.type === 'file' && /\.(ya?ml)$/i.test(f.name));
  const ignored = ['taomay.yml', 'taomay.yaml', 'taomaygoc.yml', 'bot.yml', 'botcuadat.yml'];
  const machineFiles = ymlFiles.filter(f => !ignored.includes(f.name.toLowerCase()));

  const scannedMachines = [];
  let upgradedCount = 0;
  let tplText = null;
  if (upgradeToLatest) {
    try { tplText = await loadTemplate(); } catch {}
  }

  for (const file of machineFiles) {
    try {
      const fDetail = await gh('GET', RUNNER_REPO, `/contents/${file.path}`);
      if (!fDetail || !fDetail.content) continue;
      const rawYml = Buffer.from(fDetail.content.replace(/\s+/g, ''), 'base64').toString('utf8');

      const idM = rawYml.match(/machine_id:[\s\S]*?default:\s*['"]([^'"]+)['"]/i);
      const nameM = rawYml.match(/display_name:[\s\S]*?default:\s*['"]([^'"]+)['"]/i);
      const durM = rawYml.match(/duration:[\s\S]*?default:\s*['"]([^'"]+)['"]/i);
      const pinM = rawYml.match(/fixed_password:[\s\S]*?default:\s*['"]([^'"]+)['"]/i);
      const storageM = rawYml.match(/storage_repo:[\s\S]*?default:\s*['"]([^'"]+)['"]/i);

      const mId = (idM && idM[1]) || file.name.replace(/\.(ya?ml)$/i, '');
      const dName = (nameM && nameM[1]) || `Máy ${mId}`;
      const dur = (durM && durM[1]) || '5h00m';
      const pin = (pinM && pinM[1]) || 'Aistv2026';
      const stRepo = (storageM && storageM[1]) || STORAGE_REPO;

      const mObj = store.machines[mId] = R.machines[mId] = store.machines[mId] || { name: mId, createdAt: Date.now() };
      mObj.name = mId;
      mObj.displayName = dName;
      mObj.duration = dur;
      mObj.durationMin = parseDur(dur).min;
      mObj.gvPin = pin;
      mObj.storageRepo = stRepo;
      mObj.filePath = file.path;

      // Nâng cấp file lên bản template mới nhất nếu có cập nhật
      if (upgradeToLatest && tplText) {
        const newContent = prepareWorkflow(tplText, mId, dur, pin);
        if (!rawYml.includes('uuyc_4.43.1.exe') || !rawYml.includes('ProtectedData::Protect') || !rawYml.includes('StarDesk_1.5.3.exe')) {
          await pushWorkflow(mId, newContent);
          upgradedCount++;
          await new Promise(r => setTimeout(r, 1200));
        }
      }

      scannedMachines.push(mObj);
    } catch (err) {
      console.error(`Lỗi quét file ${file.name}:`, err.message);
    }
  }

  return {
    totalFiles: ymlFiles.length,
    scannedCount: scannedMachines.length,
    upgradedCount,
    machines: scannedMachines
  };
}

// ----------------- RENDER BẢNG CANVAS DASHBOARD (!may) -----------------
async function buildDashboardPayload(targetUserId, forceRefresh = false) {
  const allNames = Object.keys(store.machines);
  const myNames = isRootUser(targetUserId)
    ? allNames
    : allNames.filter(n => store.machines[n] && store.machines[n].ownerId === targetUserId);

  let onlineCount = 0;
  let offlineCount = 0;
  const machineCards = [];

  for (const name of myNames) {
    const curM = await syncMachine(name, forceRefresh);
    const isOnline = (curM.status === 'in_progress' && (curM.isOnline || curM.ready)) || (curM.repoStatus === 'Online' && curM.status !== 'completed');
    if (isOnline) onlineCount++;
    else offlineCount++;

    const icon = isOnline ? '🟢' : (curM.status === 'in_progress' ? '⏳' : '🔴');
    const idText = curM.gvId ? `\`${curM.gvId}\`` : '*(Chờ cấp ID)*';
    const rawPin = curM.gvPin || 'Aistv2026';
    const displayPin = store.pinMasked ? '`••••••••`' : `\`${rawPin}\``;
    const remText = curM.remainSec != null && curM.status === 'in_progress' ? `Còn: **${hms(curM.remainSec)}**` : `Thời lượng: **${curM.duration || '5h'}**`;

    machineCards.push(`• ${icon} **${name.toUpperCase()}** | 🆔 ID: ${idText} | 🔑 PIN: ${displayPin} | ⏰ ${remText}`);
  }

  const maskStatusText = store.pinMasked ? '🙈 Đang ẩn (An toàn)' : '👁️ Đang hiện (Công khai)';
  const totalCount = myNames.length;

  const cardLines = [
    `🎮 **BẢNG ĐIỀU KHIỂN MÁY ẢO GAMEVIEWER & STARDESK**`,
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
    `📊 **Thống Kê:** 🟢 **${onlineCount} Online** · 🔴 **${offlineCount} Offline** · 📦 **${totalCount} Máy**`,
    `🏃 **Runner Repo:** \`${RUNNER_REPO}\``,
    `📦 **Storage Repo:** \`${STORAGE_REPO}\``,
    `👤 **Người điều khiển:** <@${targetUserId}>`,
    `🔒 **Chế độ mã PIN:** ${maskStatusText}`,
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
    machineCards.length ? machineCards.join('\n') : `*(Bạn chưa có máy nào. Bấm nút **➕ Tạo Máy Mới** bên dưới để bắt đầu!)*`,
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
    `💡 *Bấm **🚀 Bắt Đầu / Quản Lý** để mở bảng ẩn điều khiển liên tục không spam chat!*`
  ];

  const buttons = [
    [
      { id: 'p:mgr', label: '🚀 Bắt Đầu / Quản Lý', style: 'primary', ephemeral: true },
      { id: 'p:create', label: '➕ Tạo Máy Mới', style: 'success', ephemeral: true },
      { id: 'p:scan', label: '🔄 Quét & Nâng Cấp YML', style: 'secondary', ephemeral: true }
    ],
    [
      { id: 'p:toggle_pin', label: store.pinMasked ? '👁️ Hiện Mã PIN' : '🙈 Ẩn Mã PIN', style: 'secondary' },
      { id: 'p:refresh', label: '🔄 Làm Mới Trạng Thái', style: 'secondary' }
