// ============================================================================
// XỬ LÝ SỰ KIỆN: NÚT BẤM (BUTTON INTERACTIONS)
// ============================================================================
if (ev === 'button') {
  const customId = String((ctx.interaction && ctx.interaction.customId) || '');
  const parts = customId.split(':');
  const prefix = parts[0];
  const act = parts[1];
  const name = parts[2] || '';
  const val = parts[3] || '';
  const clickerId = userId;

  // 1. Kiểm tra quyền dùng bot
  if (!isAllowedUser(clickerId)) {
    return ui.reply({ content: `⛔ Bạn chưa được cấp quyền sử dụng hệ thống máy ảo! Hãy liên hệ Admin (<@${ROOT_ADMIN}>).`, ephemeral: true });
  }

  // --- NÚT TỪ BẢNG CHÍNH ---
  // Bật/Tắt ẩn mã PIN trên Dashboard
  if (prefix === 'p' && act === 'toggle_pin') {
    store.pinMasked = !store.pinMasked;
    const dash = await buildDashboardPayload(clickerId);
    return ui.reply(dash);
  }

  // Làm mới trạng thái Dashboard
  if (prefix === 'p' && act === 'refresh') {
    const dash = await buildDashboardPayload(clickerId, true);
    return ui.reply(dash);
  }

  // Mở Bảng Ẩn Quản Lý Liên Tục
  if (prefix === 'p' && act === 'mgr') {
    const mgr = await buildManagerPayload(clickerId);
    return ui.reply({ ...mgr, ephemeral: true });
  }

  // Mở Bảng Ẩn Tạo Máy Mới
  if (prefix === 'p' && act === 'create') {
    const card = [
      `➕ **TẠO MÁY ẢO MỚI (BẢNG ẨN)**`,
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
      `👉 **Chọn một mã PIN mẫu bên dưới để tạo máy nhanh:**`,
      `• Tên máy mặc định: \`may-${Date.now().toString(36).slice(-4)}\``,
      `• Hoặc bạn có thể chat trực tiếp lệnh:`,
      `  \`!may tao <tên> [1h|3h|5h] [mã_pin]\` *(VD: \`!may tao game1 5h Aistv2026\`)*`,
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`
    ].join('\n');

    const autoName = `may-${Date.now().toString(36).slice(-4)}`;
    const btns = [
      [
        { id: `quickcreate:${autoName}:Aistv2026:5h`, label: '🔑 PIN Aistv2026 (5h)', style: 'primary', ephemeral: true },
        { id: `quickcreate:${autoName}:Admin8888:5h`, label: '🔑 PIN Admin8888 (5h)', style: 'secondary', ephemeral: true },
        { id: `quickcreate:${autoName}:rnd:5h`, label: '🎲 PIN Random (5h)', style: 'secondary', ephemeral: true }
      ],
      [
        { id: 'act:close', label: '❌ Đóng Bảng Tạo', style: 'danger', ephemeral: true }
      ]
    ];
    return ui.reply({ content: card, buttons: btns, ephemeral: true });
  }

  // Quét và nâng cấp YML từ Runner Repo
  if (prefix === 'p' && act === 'scan') {
    await ui.reply({ content: `⏳ Đang quét toàn bộ file \`.yml\` trên Runner Repo (\`${RUNNER_REPO}\`) và cập nhật bản mới...`, ephemeral: true });
    try {
      const res = await scanAndRebuildWorkflows(true);
      const msg = [
        `🎉 **HOÀN TẤT ĐỒNG BỘ & NÂNG CẤP WORKFLOW!**`,
        `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
        `• 📁 **Tổng số file trong workflows:** **${res.totalFiles}**`,
        `• 🖥️ **Số máy đã nhận diện:** **${res.scannedCount}** máy`,
        `• 🚀 **Số file đã nâng cấp lên bản taomay.yml mới nhất:** **${res.upgradedCount}** file`,
        `• 🏃 **Runner Repo:** \`${RUNNER_REPO}\``,
        `• 📦 **Storage Repo:** \`${STORAGE_REPO}\``,
        `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
        `💡 *Tất cả các máy đều đã được tích hợp GameViewer 4.43.1 + StarDesk 1.5.3 + Bảo toàn phiên DPAPI!*`
      ].join('\n');
      return ui.reply({ content: msg, ephemeral: true });
    } catch (err) {
      return ui.reply({ content: `❌ Lỗi quét runner repo: ${err.message}`, ephemeral: true });
    }
  }

  // --- NÚT TẠO NHANH TỪ BẢNG TẠO ---
  if (prefix === 'quickcreate') {
    const qName = act;
    let qPin = name;
    const qDur = val || '5h';
    if (qPin === 'rnd') qPin = generateRandomPin();

    await ui.reply({ content: `⏳ Đang khởi tạo máy **${qName}** (${qDur}) với mã PIN \`${qPin}\`...`, ephemeral: true });
    try {
      const d = parseDur(qDur);
      await doCreateMachine(qName, d.input, d.min, qPin, clickerId, userDisplay);
      const mgr = await buildManagerPayload(clickerId, qName);
      return ui.reply({ content: `✅ Đã tạo máy **${qName}** thành công!\n\n` + mgr.content, buttons: mgr.buttons, ephemeral: true });
    } catch (err) {
      return ui.reply({ content: `❌ Lỗi tạo máy **${qName}**: ${err.message}`, ephemeral: true });
    }
  }

  // --- CÁC NÚT ĐIỀU HƯỚNG TRONG BẢNG ẨN (CONTINUOUS EDITING) ---
  if (prefix === 'nav') {
    const allNames = Object.keys(store.machines);
    const myNames = isRootUser(clickerId)
      ? allNames
      : allNames.filter(n => store.machines[n] && store.machines[n].ownerId === clickerId);

    const curIdx = myNames.indexOf(name);
    let nextIdx = curIdx;
    if (act === 'prev') nextIdx = (curIdx - 1 + myNames.length) % myNames.length;
    else if (act === 'next') nextIdx = (curIdx + 1) % myNames.length;

    const targetName = myNames[nextIdx] || name;
    const mgr = await buildManagerPayload(clickerId, targetName);
    return ui.reply({ ...mgr, ephemeral: true });
  }

  // Đóng Bảng Ẩn
  if (prefix === 'act' && act === 'close') {
    return ui.reply({ content: `👋 Đã đóng bảng điều khiển. Gõ \`!may\` để mở lại bất cứ lúc nào!`, ephemeral: true });
  }

  // Ẩn/Hiện PIN trong bảng ẩn
  if (prefix === 'act' && act === 'toggle_pin') {
    store.pinMasked = !store.pinMasked;
    const mgr = await buildManagerPayload(clickerId, name);
    return ui.reply({ ...mgr, ephemeral: true });
  }

  // Đổi mã PIN trong Bảng Ẩn (Có sẵn danh sách mã PIN)
  if (prefix === 'setpin') {
    const m = store.machines[act];
    if (m && m.ownerId && !canManageMachine(m, clickerId)) {
      return ui.reply({ content: `⛔ Bạn không có quyền sửa máy **${act}**!`, ephemeral: true });
    }
    let newPin = name;
    if (newPin === 'rnd') newPin = generateRandomPin();
    const v = validatePin(newPin);
    if (!v.ok) return ui.reply({ content: `❌ ${v.error}`, ephemeral: true });

    if (m) m.gvPin = v.pin;
    const curM = store.machines[act] = R.machines[act] = store.machines[act] || { name: act };
    curM.gvPin = v.pin;

    // Cập nhật lại workflow nếu có
    try {
      const tpl = await loadTemplate();
      const updatedYml = prepareWorkflow(tpl, act, curM.duration || '5h00m', v.pin);
      await pushWorkflow(act, updatedYml);
    } catch {}

    const mgr = await buildManagerPayload(clickerId, act);
    return ui.reply({
      content: `🔑 Đã cập nhật mã PIN máy **${act}** thành: \`${v.pin}\`!\n\n` + mgr.content,
      buttons: mgr.buttons,
      ephemeral: true
    });
  }

  // Đổi thời lượng trong Bảng Ẩn
  if (prefix === 'setdur') {
    const m = store.machines[act];
    if (m && m.ownerId && !canManageMachine(m, clickerId)) {
      return ui.reply({ content: `⛔ Bạn không có quyền sửa máy **${act}**!`, ephemeral: true });
    }
    const d = parseDur(name);
    if (m) {
      m.duration = d.input;
      m.durationMin = d.min;
    }
    const mgr = await buildManagerPayload(clickerId, act);
    return ui.reply({
      content: `⏱️ Đã đặt thời lượng máy **${act}** thành **${d.input}**!\n\n` + mgr.content,
      buttons: mgr.buttons,
      ephemeral: true
    });
  }

  // Các thao tác điều khiển: Bật, Khởi Động Lại, Tắt, Reload ID/PIN, Xóa
  if (prefix === 'act') {
    const mName = name;
    const m = store.machines[mName] || R.machines[mName];
    if (m && m.ownerId && !canManageMachine(m, clickerId)) {
      return ui.reply({ content: `⛔ Bạn không có quyền điều khiển máy **${mName}**!`, ephemeral: true });
    }

    // 1. Bật máy
    if (act === 'start') {
      const d = parseDur(m && m.duration || '5h00m');
      const pin = (m && m.gvPin) || 'Aistv2026';
      try {
        await triggerRun(mName, d.input, pin);
        if (m) { m.status = 'starting'; m.startedAt = Date.now(); }
        const mgr = await buildManagerPayload(clickerId, mName);
        return ui.reply({ content: `▶️ Đã gửi lệnh bật máy **${mName}** (${d.input})!\n\n` + mgr.content, buttons: mgr.buttons, ephemeral: true });
      } catch (e) {
        return ui.reply({ content: `❌ Lỗi bật máy **${mName}**: ${e.message}`, ephemeral: true });
      }
    }

    // 2. Khởi động lại
    if (act === 'restart') {
      const curM = await syncMachine(mName);
      if (curM.runId && curM.status === 'in_progress') {
        try { await gh('POST', RUNNER_REPO, `/actions/runs/${curM.runId}/cancel`); } catch {}
        await new Promise(r => setTimeout(r, 3500));
      }
      try {
        await triggerRun(mName, curM.duration || '5h00m', curM.gvPin || 'Aistv2026');
        curM.status = 'starting';
        curM.startedAt = Date.now();
        curM.gvId = null;
        const mgr = await buildManagerPayload(clickerId, mName);
        return ui.reply({ content: `🔁 Đã gửi lệnh lưu ổ đĩa và kích hoạt phiên mới cho máy **${mName}**!\n\n` + mgr.content, buttons: mgr.buttons, ephemeral: true });
      } catch (e) {
        return ui.reply({ content: `❌ Lỗi khởi động lại: ${e.message}`, ephemeral: true });
      }
    }

    // 3. Tắt máy
    if (act === 'stop') {
      const curM = await syncMachine(mName);
      if (!curM.runId || curM.status === 'completed') {
        return ui.reply({ content: `⚠️ Máy **${mName}** hiện không có phiên nào đang chạy.`, ephemeral: true });
      }
      try {
        await gh('POST', RUNNER_REPO, `/actions/runs/${curM.runId}/cancel`);
        curM.status = 'completed';
        const mgr = await buildManagerPayload(clickerId, mName);
        return ui.reply({ content: `🛑 Đã gửi lệnh lưu ổ đĩa và tắt máy **${mName}**!\n\n` + mgr.content, buttons: mgr.buttons, ephemeral: true });
      } catch (e) {
        return ui.reply({ content: `❌ Không tắt được máy: ${e.message}`, ephemeral: true });
      }
    }

    // 4. Lấy lại ID/PIN
    if (act === 'reload') {
      const curM = await syncMachine(mName, true);
      const mgr = await buildManagerPayload(clickerId, mName);
      const msg = curM.gvId ? `✅ Đã cập nhật thông tin Device ID: \`${curM.gvId}\`!` : `⏳ Máy đang đăng ký ID với NetEase, vui lòng bấm lại sau 15-30s!`;
      return ui.reply({ content: msg + '\n\n' + mgr.content, buttons: mgr.buttons, ephemeral: true });
    }

    // 5. Xóa máy
    if (act === 'del') {
      const filePath = `.github/workflows/${mName}.yml`;
      try {
        const cur = await gh('GET', RUNNER_REPO, `/contents/${filePath}`);
        if (cur && cur.sha) {
          await gh('DELETE', RUNNER_REPO, `/contents/${filePath}`, { message: `Xóa workflow ${mName}`, sha: cur.sha });
        }
      } catch {}
      delete store.machines[mName];
      delete R.machines[mName];
      const mgr = await buildManagerPayload(clickerId);
      return ui.reply({ content: `🗑️ Đã xóa máy **${mName}** thành công!\n\n` + mgr.content, buttons: mgr.buttons, ephemeral: true });
    }
  }

  return;
}

// ============================================================================
// XỬ LÝ SỰ KIỆN: LỆNH CHAT (!may)
// ============================================================================
const raw = String(ctx.content || (ctx.message && ctx.message.content) || ctx.rest || '').trim();
let words = (ctx.args && Array.isArray(ctx.args) && ctx.args.length)
  ? [...ctx.args]
  : raw.split(/\s+/).filter(Boolean);

if (words[0] && /^!(may|thongtin|rdp)\b/i.test(words[0])) {
  words.shift();
}

const a = words;
const sub = (a[0] || '').toLowerCase();
const arg = a[1] || '';

// ----------------- KIỂM TRA QUYỀN -----------------
if (!isAllowedUser(userId)) {
  return say(`⛔ Bạn chưa được cấp quyền sử dụng hệ thống máy ảo! Hãy liên hệ Admin (<@${ROOT_ADMIN}>) để được cấp phép.`);
}

// ============================================================================
// 1. LỆNH CHẠY DUY NHẤT: !may (KHÔNG CẦN GÕ THÊM LỆNH PHỤ)
// ============================================================================
if (!sub || sub === 'menu' || sub === 'panel' || sub === 'dashboard') {
  say('🔄 Đang đồng bộ thông tin máy ảo...');
  const dash = await buildDashboardPayload(userId);
  return say(dash.content, { buttons: dash.buttons });
}

// ============================================================================
// 2. LỆNH QUÉT & NÂNG CẤP WORKFLOWS (!may scan HOẶC !may quet)
// ============================================================================
if (sub === 'scan' || sub === 'quet' || sub === 'sync') {
  say(`⏳ Đang quét toàn bộ file \`.yml\` trên Runner Repo (\`${RUNNER_REPO}\`) và tự động nâng cấp...`);
  try {
    const res = await scanAndRebuildWorkflows(true);
    const msg = [
      `🎉 **HOÀN TẤT ĐỒNG BỘ & NÂNG CẤP TOÀN BỘ MÁY ẢO!**`,
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
      `• 📁 **Tổng số file trong workflows:** **${res.totalFiles}**`,
      `• 🖥️ **Số máy đã nhận diện:** **${res.scannedCount}** máy`,
      `• 🚀 **Số file đã cập nhật lên bản taomay.yml mới nhất:** **${res.upgradedCount}** file`,
      `• 🏃 **Runner Repo:** \`${RUNNER_REPO}\``,
      `• 📦 **Storage Repo:** \`${STORAGE_REPO}\``,
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
      `💡 *Gõ \`!may\` để mở bảng điều khiển quản lý ngay!*`
    ].join('\n');
    return say(msg);
  } catch (err) {
    return say(`❌ Lỗi quét runner repo: ${err.message}`);
  }
}

// ============================================================================
// 3. LỆNH NHẬP MÃ PIN THỦ CÔNG (!may pin <mã_pin>)
// ============================================================================
if (sub === 'pin') {
  const pending = store.pendingCreate[userId];
  if (!pending) {
    return say(`⚠️ Bạn chưa có yêu cầu tạo máy nào đang chờ mã PIN. Hãy gõ \`!may tao <tên> [thời_gian]\` trước!`);
  }

  const customPin = (arg || '').trim();
  const v = validatePin(customPin);
  if (!v.ok) {
    return say(`❌ ${v.error}\n💡 Mã PIN phải gồm 8-16 ký tự chữ và số (VD: \`Aistv2026\`, \`Admin8888\`).`);
  }

  const { name, duration: dInput, durationMin: dMin } = pending;
  delete store.pendingCreate[userId];

  say(`⏳ Đang khởi tạo máy **${name}** với mã PIN: \`${v.pin}\`...`);
  try {
    const resMsg = await doCreateMachine(name, dInput, dMin, v.pin, userId, userDisplay);
    const mgr = await buildManagerPayload(userId, name);
    return say(resMsg.text, { buttons: mgr.buttons });
  } catch (err) {
    return say(`❌ Lỗi tạo máy **${name}**: ${err.message}`);
  }
}

// ============================================================================
// 4. LỆNH TẠO MÁY MỚI (!may tao <tên> [thời_gian] [mã_pin])
// ============================================================================
if (sub === 'tao' || sub === 'taolai') {
  const name = nameOk(arg);
  if (!name) return say('Thiếu tên máy. VD: `!may tao chill 5h`');
  if (['bot', 'taomay', 'may-goc'].includes(name)) return say(`Tên \`${name}\` bị giữ chỗ, hãy chọn tên khác.`);

  const existing = store.machines[name] || R.machines[name];
  if (existing && existing.ownerId && existing.ownerId !== userId && !isRootUser(userId)) {
    return say(`⛔ Tên máy **${name}** đã được đăng ký bởi <@${existing.ownerId}>. Vui lòng chọn tên khác!`);
  }

  let durInput = '5h00m';
  let durMin = 300;
  let customPin = null;

  const arg2 = a[2] || '';
  const arg3 = a[3] || '';

  if (/^[135]h?$/i.test(arg2)) {
    const d = parseDur(arg2);
    durInput = d.input;
    durMin = d.min;
    if (arg3) customPin = arg3;
  } else if (/^[135]h?$/i.test(arg3)) {
    const d = parseDur(arg3);
    durInput = d.input;
    durMin = d.min;
    if (arg2) customPin = arg2;
  } else if (arg2) {
    customPin = arg2;
  }

  if (customPin) {
    const v = validatePin(customPin);
    if (!v.ok) return say(`❌ ${v.error}\n💡 Mã PIN phải gồm 8-16 ký tự chữ và số.`);
    say(`⏳ Đang tạo máy **${name}** (${durInput}) với mã PIN: \`${v.pin}\`...`);
    try {
      const resMsg = await doCreateMachine(name, durInput, durMin, v.pin, userId, userDisplay);
      const mgr = await buildManagerPayload(userId, name);
      return say(resMsg.text, { buttons: mgr.buttons });
    } catch (err) {
      return say(`❌ Lỗi tạo máy **${name}**: ${err.message}`);
    }
  }

  // Nếu chưa có PIN: hiển thị bảng chọn PIN
  store.pendingCreate[userId] = { name, duration: durInput, durationMin: durMin, time: Date.now() };
  const pinPrompt = [
    `🔐 **CÀI ĐẶT MÃ PIN CHO MÁY [${name.toUpperCase()}]**`,
    `• 🏷️ **Tên máy:** **${name}** · ⏰ **Thời lượng:** **${durInput}**`,
    `• ℹ️ *Quy định GameViewer:* Mã PIN gồm **8 đến 16 ký tự** chữ và số (chứa cả hai).`,
    ``,
    `👉 **Chọn một mã PIN có sẵn bên dưới hoặc chat \`!may pin <mã_pin>\`:**`
  ].join('\n');

  const pinButtons = [
    [
      { id: `quickcreate:${name}:Aistv2026:${durInput}`, label: '🔑 PIN Aistv2026', style: 'primary', ephemeral: true },
      { id: `quickcreate:${name}:Admin8888:${durInput}`, label: '🔑 PIN Admin8888', style: 'secondary', ephemeral: true },
      { id: `quickcreate:${name}:Game2026:${durInput}`, label: '🔑 PIN Game2026', style: 'secondary', ephemeral: true },
      { id: `quickcreate:${name}:rnd:${durInput}`, label: '🎲 PIN Random', style: 'secondary', ephemeral: true }
    ],
    [
      { id: 'act:close', label: '❌ Hủy Bỏ', style: 'danger', ephemeral: true }
    ]
  ];

  return say(pinPrompt, { buttons: pinButtons });
}

// ============================================================================
// 5. CÁC LỆNH ĐIỀU KHIỂN NHANH (SHORTCUTS CHO LỆNH CHAT)
// ============================================================================
if (sub === 'chay' || sub === 'start') {
  const name = nameOk(arg);
  if (!name) return say('Dùng: `!may chay <tên_máy>`');
  const m = store.machines[name] || R.machines[name];
  if (m && m.ownerId && !canManageMachine(m, userId)) return say(`⛔ Không có quyền điều khiển máy **${name}**!`);
  const d = parseDur(a[2] || (m && m.duration) || '5h00m');
  const pin = (m && m.gvPin) || 'Aistv2026';

  say(`⏳ Đang kích hoạt máy **${name}** (${d.input})...`);
  try {
    await triggerRun(name, d.input, pin);
    const mgr = await buildManagerPayload(userId, name);
    return say(`▶️ Đã gửi lệnh khởi chạy máy **${name}** (${d.input})!`, { buttons: mgr.buttons });
  } catch (err) {
    return say(`❌ Lỗi chạy máy: ${err.message}`);
  }
}

if (sub === 'tat' || sub === 'stop') {
  const name = nameOk(arg);
  if (!name) return say('Dùng: `!may tat <tên_máy>`');
  const curM = await syncMachine(name);
  if (!curM.runId || curM.status === 'completed') return say(`Máy **${name}** hiện không có phiên nào đang chạy.`);
  try {
    await gh('POST', RUNNER_REPO, `/actions/runs/${curM.runId}/cancel`);
    return say(`🛑 Đã gửi lệnh lưu ổ đĩa và tắt máy **${name}**.`);
  } catch (err) {
    return say(`❌ Lỗi tắt máy: ${err.message}`);
  }
}

if (sub === 'khoi-dong-lai' || sub === 'restart') {
  const name = nameOk(arg);
  if (!name) return say('Dùng: `!may khoi-dong-lai <tên_máy>`');
  const curM = await syncMachine(name);
  if (curM.runId && curM.status === 'in_progress') {
    say(`🛑 Đang lưu ổ đĩa và tắt phiên cũ của máy **${name}**...`);
    try { await gh('POST', RUNNER_REPO, `/actions/runs/${curM.runId}/cancel`); } catch {}
    await new Promise(r => setTimeout(r, 3500));
  }
  try {
    await triggerRun(name, curM.duration || '5h00m', curM.gvPin || 'Aistv2026');
    const mgr = await buildManagerPayload(userId, name);
    return say(`🔁 Đã lưu ổ đĩa và kích hoạt phiên mới cho máy **${name}**!`, { buttons: mgr.buttons });
  } catch (err) {
    return say(`❌ Lỗi khởi động lại: ${err.message}`);
  }
}

if (sub === 'xoa' || sub === 'del') {
  const name = nameOk(arg);
  if (!name) return say('Dùng: `!may xoa <tên_máy>`');
  const filePath = `.github/workflows/${name}.yml`;
  try {
    const cur = await gh('GET', RUNNER_REPO, `/contents/${filePath}`);
    if (cur && cur.sha) await gh('DELETE', RUNNER_REPO, `/contents/${filePath}`, { message: `Xóa workflow ${name}`, sha: cur.sha });
  } catch {}
  delete store.machines[name];
  delete R.machines[name];
  return say(`🗑️ Đã xóa máy **${name}** thành công!`);
}

// ============================================================================
// 6. LỆNH QUẢN TRỊ ADMIN (ĐỔI REPO & PHÂN QUYỀN)
// ============================================================================
if (sub === 'doirepo') {
  if (!isRootUser(userId)) return say(`⛔ Chỉ Root Admin mới có quyền đổi Runner Repo!`);
  const newRepo = (arg || '').trim();
  const newToken = (a[2] || '').trim();
  if (!newRepo || !newRepo.includes('/')) return say('Dùng: `!may doirepo <owner/repo_mới> [token_pat]`');
  store.config = store.config || {};
  R.config = R.config || {};
  store.config.runnerRepo = R.config.runnerRepo = newRepo;
  if (newToken) store.config.token = R.config.token = newToken;
  return say(`✅ Đã chuyển Runner Repo thành: \`${newRepo}\` (Kho ổ đĩa gốc \`${STORAGE_REPO}\` an toàn 100%)!`);
}

if (sub === 'taolaitatca') {
  if (!isRootUser(userId)) return say(`⛔ Chỉ Root Admin mới có quyền thực hiện!`);
  say(`⏳ Đang tự động quét và nâng cấp toàn bộ máy sang Runner Repo mới...`);
  try {
    const res = await scanAndRebuildWorkflows(true);
    return say(`🎉 Đã đồng bộ lại thành công **${res.upgradedCount}** máy sang \`${RUNNER_REPO}\`!`);
  } catch (e) {
    return say(`❌ Lỗi: ${e.message}`);
  }
}

if (sub === 'capquyen') {
  if (!isRootUser(userId)) return say(`⛔ Chỉ Root Admin mới có quyền cấp phép!`);
  const targetId = (arg || '').replace(/[<@!>]/g, '').trim();
  if (!targetId || !/^\d{16,21}$/.test(targetId)) return say('Dùng: `!may capquyen <@user hoặc ID>`');
  store.allowedUsers[targetId] = { id: targetId, by: userDisplay, at: Date.now() };
  return say(`✅ Đã cấp quyền sử dụng bot cho <@${targetId}>!`);
}

if (sub === 'thuquyen') {
  if (!isRootUser(userId)) return say(`⛔ Chỉ Root Admin mới có quyền thu hồi!`);
  const targetId = (arg || '').replace(/[<@!>]/g, '').trim();
  if (targetId === ROOT_ADMIN) return say('❌ Không thể thu hồi quyền Root Admin!');
  delete store.allowedUsers[targetId];
  return say(`🗑️ Đã thu hồi quyền sử dụng bot của <@${targetId}>!`);
}

if (sub === 'dsquyen') {
  const list = Object.keys(store.allowedUsers || {});
  const lines = [`👑 **DANH SÁCH THÀNH VIÊN ĐƯỢC CẤP QUYỀN:**`, `• 👑 **Root Admin:** <@${ROOT_ADMIN}>`];
  list.filter(id => id !== ROOT_ADMIN).forEach(id => lines.push(`• 👤 <@${id}>`));
  return say(lines.join('\n'));
}

// 7. LỆNH KHÔNG XÁC ĐỊNH -> HIỂN THỊ DASHBOARD CHÍNH
const dash = await buildDashboardPayload(userId);
return say(dash.content, { buttons: dash.buttons });

embed.description:
Cảnh giới hiện tại: {realmEmoji} **{realm}** · {tierName}
Tu vi: `{bar}`

*Đại La ngự trị tại Thái Sơ… còn ngươi, đang ở đâu giữa hỗn độn?*

commands.code:
// TREO TU LUYỆN — role cấp cao (gán ở trang Tu Tiên › Role & liên kết; role “tự động” khỏi cần gõ lệnh). Gõ: !ttreo (bật / thu hoạch) · !ttreo tat (thu hoạch rồi dừng) · !ttreo xem
// Không cần bấm "Tu luyện": tu vi tích theo thời gian thực, gõ lệnh là nhận phần đã tích (tự lên tầng).
const ROLE_IDS = [];          // ID role cấp cao được treo, vd ['123456789012345678']. Admin / chủ server luôn được.
const ROLE_NAMES = [];        // hoặc theo tên role, vd ['VIP', 'Trưởng lão']
const INTERVAL_SEC = 60;      // cứ N giây treo = 1 lần tu luyện
const EFFICIENCY = 1;         // hiệu suất so với bấm tay (1 = bằng, 2 = gấp đôi ...)
const MAX_HOURS = 8;          // mỗi lần thu hoạch tối đa N giờ (quá giờ thì phần dư mất)
const MIN_REALM = 0;          // chỉ cho treo từ cảnh giới số mấy (0 = Phàm Nhân, 3 = Luyện Khí Hóa Thần)

const u = ctx.user, p = shared.player;
const allowed = u.isAdmin || u.isOwner || (ctx.idle && ctx.idle.mode !== 'none') || ROLE_IDS.some(id => u.roleIds.includes(String(id))) || ROLE_NAMES.some(n => u.roles.includes(n));
if (!allowed) { reply('🔒 ' + u.mention + ' chỉ role cấp cao mới được **treo tu luyện**.'); return; }
if (ctx.player.realmIdx < MIN_REALM) { reply('🚫 Cần đạt cảnh giới số **' + MIN_REALM + '** trở lên mới được treo.'); return; }

p.flags = p.flags || {};
const EFF = EFFICIENCY * ((ctx.idle && ctx.idle.mult) || 1);   // hệ số theo role (tab Role & liên kết)
if (ctx.idle && ctx.idle.mode === 'auto') { const f = p.flags.auto; reply('♾️ ' + u.mention + ' thuộc role **tự động treo**: không cần gõ lệnh, tu vi tự tích theo thời gian (đã tích ≈ **' + Math.floor((f && f.total) || 0) + '** lần tu luyện).'); return; }
const now = ctx.now, arg = (ctx.args[0] || '').toLowerCase();
const dur = s => { s = Math.floor(s); const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60); return (h ? h + ' giờ ' : '') + m + ' phút'; };
const OFF = ['tat', 'tắt', 'off', 'dung', 'dừng', 'stop'], VIEW = ['xem', 'status', 'tt'];
let idle = p.flags.idle;

function settle() {                         // đổi thời gian đã treo thành số lần tu luyện
  const capMs = MAX_HOURS * 3600 * 1000, el = Math.max(0, now - idle.last), used = Math.min(el, capMs);
  const trains = Math.min(5000, used / 1000 / INTERVAL_SEC * EFF);
  idle.last = now; idle.total = (idle.total || 0) + trains;
  p.addTrains = trains;
  return { used, lost: el - used, trains };
}

if (VIEW.includes(arg)) {
  if (!idle || !idle.on) reply('💤 Đang **không treo**. Gõ \`!ttreo\` để bắt đầu.');
  else { const el = Math.min(now - idle.last, MAX_HOURS * 3600000); reply('🧘 Đang treo **' + dur((now - idle.since) / 1000) + '** · chờ thu hoạch ≈ **' + Math.floor(el / 1000 / INTERVAL_SEC * EFF) + '** lần tu luyện (tối đa ' + MAX_HOURS + ' giờ).'); }
} else if (OFF.includes(arg)) {
  if (!idle || !idle.on) reply('💤 Ngươi đang không treo.');
  else { const r = settle(); idle.on = false; reply('🛑 Dừng treo sau **' + dur((now - idle.since) / 1000) + '**. Thu hoạch ≈ **' + Math.floor(r.trains) + '** lần tu luyện.'); }
} else if (!idle || !idle.on) {
  p.flags.idle = { on: true, since: now, last: now, total: (idle && idle.total) || 0 };
  reply('🧘 ' + u.mention + ' bắt đầu **treo tu luyện** (1 lần / ' + INTERVAL_SEC + 's, tối đa ' + MAX_HOURS + ' giờ mỗi lượt thu). Gõ \`!ttreo\` lại để thu hoạch, \`!ttreo tat\` để dừng.');
} else {
  const r = settle();
  reply('🧘 Thu hoạch sau **' + dur(r.used / 1000) + '** treo: ≈ **' + Math.floor(r.trains) + '** lần tu luyện.' + (r.lost > 0 ? '\n⚠️ Quá ' + MAX_HOURS + ' giờ nên mất ' + dur(r.lost / 1000) + '.' : '') + '\nVẫn đang treo — gõ \`!ttreo tat\` để dừng.');
}

// Lệnh script Tu Tiên. ctx.player = dữ liệu người chơi (đã định dạng), shared.player = bản thô để sửa.
// Thư viện số vô hạn: const I = require(ctx.libPath);  I.fmt([tầng, log10])
const I = require(ctx.libPath);
const p = shared.player;               // { realm, tier, exp:[a,b], dao, flags, ... }
p.dao = (p.dao || 0) + 1;              // ngộ đạo: +1 đạo ngấn
reply('☯️ ' + ctx.user.mention + ' ngộ đạo, đạo ngấn: **' + p.dao + '** (cảnh giới ' + ctx.player.realm + ')');

